<script setup lang="ts">
import {ref,reactive,onMounted,computed} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {ElMessage} from 'element-plus'
import {api,mode} from '../api'
import type {SearchPaper,PageResult} from '../types/research'
import {validYears,safeUrl} from '../api/utils'
import {useResource} from '../composables/useResource'
import AsyncState from '../components/AsyncState.vue'
import Icon from '../components/Icon.vue'
import VenueSearchWorkspace from '../components/VenueSearchWorkspace.vue'
import AbstractTranslation from '../components/AbstractTranslation.vue'
const searchMode=ref('arxiv')
const route=useRoute(),router=useRouter(),selected=ref<string[]>([]),saving=ref(false),abstract=ref<SearchPaper|null>(null),drawer=ref(false),searched=ref(false)
const form=reactive({q:String(route.query.q||''),source:'arxiv',start_year:route.query.start_year?Number(route.query.start_year):undefined,end_year:route.query.end_year?Number(route.query.end_year):undefined,sort:['relevance','newest','updated'].includes(String(route.query.sort))?String(route.query.sort):'relevance',page:Number(route.query.page||1),page_size:20})
const {data,loading,error,load}=useResource<PageResult<SearchPaper>>({items:[],total:0,page:1,page_size:20})
const key=(p:SearchPaper)=>p.arxiv_id||p.doi||p.title
const selectable=computed(()=>data.value.items.filter(p=>p.identity_verified&&!p.saved_paper_id))
async function search(reset=true){if(!form.q.trim()){ElMessage.warning('请输入研究关键词');return}if(!validYears(form.start_year,form.end_year)){ElMessage.warning('起始年份不能晚于结束年份');return}if(reset)form.page=1;searched.value=true;selected.value=[];await router.replace({query:Object.fromEntries(Object.entries(form).filter(([,v])=>v!==undefined).map(([k,v])=>[k,String(v)]))});await load(()=>api.search({...form,q:form.q.trim()}))}
async function save(items:SearchPaper[]){saving.value=true;try{const r=await api.savePapers(items);ElMessage.success(`新增 ${r.created} 篇 · 已存在 ${r.existing} 篇 · 未入库 ${r.rejected} 篇`);await search(false)}catch(e){ElMessage.error((e as Error).message)}finally{saving.value=false}}
function show(p:SearchPaper){abstract.value=p;drawer.value=true}
onMounted(()=>{if(form.q)search(false)})
</script>
<template><div class="page-heading"><div><div class="eyebrow">DISCOVER YOUR NEXT REFERENCE</div><h1>文献检索</h1><p>找到相关研究，为每一个问题建立文献起点。</p></div><RouterLink class="text-link" to="/library">我的文献库 ↗</RouterLink></div><section v-if="typeof route.query.translationId==='string'" class="panel" style="padding:22px;margin-bottom:20px"><AbstractTranslation :initial-translation-id="route.query.translationId" show-title/></section><div class="panel" style="padding:16px;margin-bottom:20px"><el-radio-group v-model="searchMode"><el-radio-button value="arxiv">arXiv 检索</el-radio-button><el-radio-button value="cvpr">顶刊顶会检索</el-radio-button></el-radio-group></div><VenueSearchWorkspace v-if="searchMode==='cvpr'"/><template v-else><form class="panel search-panel" @submit.prevent="search()"><div class="search-main"><Icon name="Search"/><el-input v-model="form.q" placeholder="输入研究主题、论文标题或关键词…" size="large" aria-label="研究关键词"/><el-button type="primary" size="large" native-type="submit" :loading="loading">检索文献 <span>↗</span></el-button></div><div class="filter-row"><label>数据来源<span class="source-label">arXiv</span></label><label>首次提交年份<div class="year-range"><el-input-number v-model="form.start_year" :controls="false" :min="1900" :max="2100" placeholder="起始年份" aria-label="起始年份"/><span>—</span><el-input-number v-model="form.end_year" :controls="false" :min="1900" :max="2100" placeholder="结束年份" aria-label="结束年份"/></div></label><label>排序方式<el-select v-model="form.sort" aria-label="排序方式"><el-option label="相关性优先" value="relevance"/><el-option label="最新提交" value="newest"/><el-option label="最近更新" value="updated"/></el-select></label></div></form><div v-if="!searched" class="search-welcome"><div class="eyebrow">START WITH A QUESTION</div><h2>你的下一个研究发现，从这里开始。</h2><p>使用英文关键词通常可以找到更广泛的学术结果。</p><div class="suggestion-row"><button v-for="q in ['monocular depth','single photon','medical image segmentation transformer']" :key="q" @click="form.q=q;search()">{{q}} <span>↗</span></button></div><p v-if="mode()==='demo'" class="note">演示模式仅展示 arXiv 示例记录；实时检索请在设置中切换到真实 API。</p></div><template v-else><div class="result-toolbar"><div><strong>检索结果</strong><span class="muted">{{data.total}} 篇论文</span></div><div><el-checkbox :model-value="!!selectable.length&&selected.length===selectable.length" @change="selected=$event?selectable.map(key):[]">全选</el-checkbox><el-button type="primary" plain :disabled="!selected.length" :loading="saving" @click="save(data.items.filter(p=>selected.includes(key(p))))">收藏选中 {{selected.length?`(${selected.length})`:''}}</el-button></div></div><AsyncState :loading="loading" :error="error" :empty="!data.items.length" title="没有找到匹配的论文" description="试试更简短的关键词，或扩大年份范围。" @retry="search(false)"><div class="search-results"><article v-for="p in data.items" :key="key(p)" class="panel paper-card"><el-checkbox v-model="selected" :value="key(p)" :disabled="!p.identity_verified||!!p.saved_paper_id" :aria-label="`选择 ${p.title}`"/><div class="paper-card-body"><div class="flex-between"><span class="source-label">ARXIV</span><span class="muted">{{p.year||'年份未知'}} · 预印本</span></div><button class="paper-title title-button" @click="show(p)">{{p.title}}</button><div class="metadata">{{p.authors.slice(0,4).join(' · ')||'作者未记录'}}</div><p class="note">原文摘要</p><p class="abstract-preview">{{p.abstract||'暂无摘要，请前往来源网站查看。'}}</p><AbstractTranslation :title="p.title" :abstract="p.abstract" :show-original="false"/><div class="paper-card-footer"><code>arXiv:{{p.arxiv_id}}</code><div class="button-row"><el-tag v-if="!p.identity_verified" type="warning" size="small">待核验</el-tag><el-tag v-else-if="p.saved_paper_id" type="success" size="small">已收藏</el-tag><button v-else class="text-link" :disabled="saving" @click="save([p])">＋ 收藏论文</button><a v-if="safeUrl(p.url)" :href="safeUrl(p.url)!" target="_blank" rel="noopener noreferrer">原站 ↗</a></div></div></div></article></div><el-pagination v-if="data.total>form.page_size" v-model:current-page="form.page" :page-size="form.page_size" :total="data.total" layout="prev,pager,next,total" @current-change="search(false)"/></AsyncState></template><el-drawer v-model="drawer" title="论文摘要" size="480px"><template v-if="abstract"><h2>{{abstract.title}}</h2><p class="muted">{{abstract.authors.join(' · ')}}</p><AbstractTranslation :title="abstract.title" :abstract="abstract.abstract"/><dl class="details-list"><dt>DOI</dt><dd>{{abstract.doi||'未记录'}}</dd><dt>arXiv</dt><dd>{{abstract.arxiv_id}}</dd><dt v-if="abstract.published_doi">正式发表 DOI</dt><dd v-if="abstract.published_doi">{{abstract.published_doi}}</dd></dl><el-button type="primary" :disabled="!abstract.identity_verified||!!abstract.saved_paper_id" @click="save([abstract])">{{abstract.saved_paper_id?'已收藏':'收藏论文'}}</el-button></template></el-drawer></template></template>
